#include "leap.h"
#include "screen_staging.h"
#include "pose.h"
#include "../flow/phase_controller.h"
#include <algorithm>
#include <cmath>
namespace speed {
namespace {
void lock(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoLeapState>(v.move);const auto &b=*PhaseController::find(r,t.actor);const auto &p=r.content->boss_techniques[t.definition-1];const auto &d=*std::find_if(r.content->draco_leaps.begin(),r.content->draco_leaps.end(),[&](const auto &d){return d.technique==t.definition;});t.aim=DracoTechnique::predict(r,t.actor,std::max(0.0,p.warn-v.stage_time)+p.active,d.lead_cap);t.direction=(t.aim-s.origin).normalized();if (t.direction.is_zero_approx()) t.direction={1,0};s.takeoff=s.origin-t.direction*70;s.destination=t.aim-t.direction*105*b.draco.head_scale;v.warning={s.takeoff+t.direction*105*b.draco.head_scale,t.aim};v.warning_width=p.width;}
}
void DracoLeap::begin(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);v.move=DracoLeapState{};DracoScreenStaging::begin(r,t,std::get<DracoLeapState>(v.move).staging,true,-0.3);t.locked=false;}
void DracoLeap::windup(RunRuntime &r,TechniqueState &t,double dt) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoLeapState>(v.move);if (!DracoScreenStaging::advance(r,t,s.staging,dt)) return;auto &e=r.state.enemies[t.actor.slot];const double warn=r.content->boss_techniques[t.definition-1].warn,setup=std::min(0.2,warn*0.3);if (!s.positioned) {s.origin=e.pos;s.positioned=true;}if (!t.locked) {lock(r,t);t.locked=v.stage_time>=setup;}e.facing+=std::remainder(t.direction.angle()-e.facing,6.283185307179586)*std::clamp(dt*9,0.0,1.0);e.pos=v.stage_time<setup?s.origin:s.origin.lerp(s.takeoff,DracoTechnique::smooth((v.stage_time-setup)/(warn-setup)));}
void DracoLeap::active(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoLeapState>(v.move);const auto &b=*PhaseController::find(r,t.actor);v.warning.clear();const auto before=DracoTechnique::mouth(r,b);r.state.enemies[t.actor.slot].pos=s.takeoff.lerp(s.destination,DracoTechnique::smooth(v.stage_time/r.content->boss_techniques[t.definition-1].active));const auto after=DracoTechnique::mouth(r,b);DracoTechnique::hit_segment(r,t,before,after,r.content->boss_techniques[t.definition-1].width,Cause::Leap);v.attack={before,after};}
void DracoLeap::end(RunRuntime &r,TechniqueState &t,bool cancelled) {auto &v=std::get<DracoTechniqueState>(t.detail);v.warning.clear();v.attack.clear();if (r.state.enemy_handles.contains(t.actor)) std::get<DracoLeapState>(v.move).landed=r.state.enemies[t.actor.slot].pos;if (cancelled) if (auto *b=PhaseController::find(r,t.actor)) DracoPose::reset(r,*b);}
void DracoLeap::recover(RunRuntime &r,TechniqueState &t) {const auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoLeapState>(v.move);r.state.enemies[t.actor.slot].pos=s.landed-t.direction*60*DracoTechnique::smooth(v.stage_time/std::max(0.001,r.content->boss_techniques[t.definition-1].recover));}
bool DracoLeap::validate(const DracoLeapState &s) {return s.origin.is_finite() && s.destination.is_finite() && s.takeoff.is_finite() && s.landed.is_finite() && DracoScreenStaging::validate(s.staging);}
godot::Dictionary DracoLeap::snapshot(const TechniqueState &t) {const auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoLeapState>(v.move);godot::Dictionary out;godot::PackedVector2Array markers;if (!v.warning.empty()) markers.push_back(t.aim);out["telegraph_points"]=markers;out["telegraph_radius"]=v.warning_width;out["staging_ready"]=s.staging.phase==2;out["staging_phase"]=s.staging.phase;out["exit_time"]=s.staging.exit_time;out["entry_time"]=s.staging.entry_time;out["staging_side"]=s.staging.side;out["origin"]=s.origin;out["destination"]=s.destination;out["takeoff"]=s.takeoff;return out;}
}
